### What is the Surrounded Regions problem?

The problem gives a board of 'X' and 'O' characters. The task is to capture all regions of 'O' that are completely surrounded by 'X' by flipping them to 'X'. An 'O' on the border or connected to a border 'O' through adjacent 'O' cells is safe and must remain 'O'. Only fully enclosed regions are captured.

```java
package com.bank.service;

public class SurroundedRegions {
    public void solve(char[][] board) {
        if (board == null || board.length == 0) return;
        int rows = board.length, cols = board[0].length;

        // Step 1: mark border-connected O's as safe (S)
        for (int r = 0; r < rows; r++) {
            if (board[r][0] == 'O') dfs(board, r, 0);
            if (board[r][cols - 1] == 'O') dfs(board, r, cols - 1);
        }
        for (int c = 0; c < cols; c++) {
            if (board[0][c] == 'O') dfs(board, 0, c);
            if (board[rows - 1][c] == 'O') dfs(board, rows - 1, c);
        }

        // Step 2: sweep - O becomes X, S becomes O
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') board[r][c] = 'X';      // enclosed
                else if (board[r][c] == 'S') board[r][c] = 'O';  // safe
            }
        }
    }

    private void dfs(char[][] board, int r, int c) {
        if (r < 0 || c < 0 || r >= board.length || c >= board[0].length
                || board[r][c] != 'O') return;
        board[r][c] = 'S'; // sentinel: safe
        dfs(board, r + 1, c);
        dfs(board, r - 1, c);
        dfs(board, r, c + 1);
        dfs(board, r, c - 1);
    }

    public static void main(String[] args) {
        char[][] board = {
            {'X', 'X', 'X', 'X'},
            {'X', 'O', 'O', 'X'},
            {'X', 'X', 'O', 'X'},
            {'X', 'O', 'X', 'X'}
        };
        new SurroundedRegions().solve(board);
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}
```

